import React from "react"
import { Dropdown, Label } from "@heroui/react"
import { TranslateIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import type { NavbarLanguageOption } from "../types"

/** Props for {@link NavbarLanguageMenu}. */
export interface NavbarLanguageMenuProps {
    languages: Array<NavbarLanguageOption>
    activeLocale: string
    onLocaleChange: (code: string) => void
}

/**
 * Locale picker ΓÇö raw HeroUI `Dropdown` (see file header: no atom here supports a
 * single-select CHECK indicator). Shared verbatim by the desktop icon row and the
 * mobile drawer row so the two never drift.
 */
export const NavbarLanguageMenu = ({ languages, activeLocale, onLocaleChange }: NavbarLanguageMenuProps) => (
    <Dropdown>
        <Button
            isIconOnly
            variant="ghost"
            prefixIcon={TranslateIcon}
            ariaLabel="Language"

        />
        <Dropdown.Popover>
            <Dropdown.Menu
                aria-label="Language"
                selectionMode="single"
                selectedKeys={new Set([activeLocale])}
                onSelectionChange={(keys) => {
                    if (keys === "all") return
                    const next = [...keys][0]
                    if (next != null) onLocaleChange(String(next))
                }}

            >
                <Dropdown.Section>
                    {languages.map((language) => (
                        <Dropdown.Item
                            key={language.code}
                            id={language.code}
                            textValue={language.label}

                        >
                            <Dropdown.ItemIndicator />
                            <Label>{language.label}</Label>
                        </Dropdown.Item>
                    ))}
                </Dropdown.Section>
            </Dropdown.Menu>
        </Dropdown.Popover>
    </Dropdown>
)

import React from "react"
import { Switch as HeroSwitch } from "@heroui/react"
import { MoonIcon, SunIcon } from "@phosphor-icons/react"

/** Props for {@link NavbarThemeSwitch}. */
export interface NavbarThemeSwitchProps {
    isDarkMode: boolean
    onThemeToggle: (isDark: boolean) => void
}

/**
 * Dark/light toggle ΓÇö raw HeroUI `Switch` (see file header: `ChoiceSwitch` has no
 * icon-in-thumb slot). Shared verbatim by the desktop row and the mobile drawer row.
 */
export const NavbarThemeSwitch = ({ isDarkMode, onThemeToggle }: NavbarThemeSwitchProps) => (
    <HeroSwitch
        isSelected={isDarkMode}
        onChange={onThemeToggle}
        aria-label="Toggle dark mode"

    >
        {({ isSelected }) => (
            <HeroSwitch.Content>
                <HeroSwitch.Control>
                    <HeroSwitch.Thumb>
                        <HeroSwitch.Icon>
                            {isSelected ? <MoonIcon className="size-5 text-inherit" /> : <SunIcon className="size-5 text-inherit" />}
                        </HeroSwitch.Icon>
                    </HeroSwitch.Thumb>
                </HeroSwitch.Control>
            </HeroSwitch.Content>
        )}
    </HeroSwitch>
)

"use client"

import React, { useCallback } from "react"
import {
    Dropdown,
    Label,
} from "@heroui/react"
import {
    SquaresFourIcon,
    UserIcon,
    FileTextIcon,
    GearIcon,
    SignOutIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { pathConfig } from "@/resources/path"
import { useAccountMenuOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useMutateSignOutSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSignOutSwr"

/** Props for {@link AccountMenuAuthed}. */
export type AccountMenuAuthedProps = Record<string, never>
/**
 * Account dropdown menu for SIGNED-IN viewers: a primary section (Dashboard ┬╖
 * Profile ┬╖ Settings) and a separated destructive section (Sign out, danger).
 * Self-contained ΓÇö owns navigation (closes the menu then pushes) and the sign-out
 * mutation; takes no data props.
 *
 * @param props - optional className (placement only).
 */
export const AccountMenuAuthed = () => {
    const t = useTranslations()
    const router = useRouter()
    const { close } = useAccountMenuOverlayState()
    const signOut = useMutateSignOutSwr()

    /** Close the menu, then navigate. */
    const go = useCallback(
        (path: string) => {
            close()
            router.push(path)
        },
        [close, router],
    )

    /** Close the menu, then sign out. */
    const onLogout = useCallback(
        async () => {
            close()
            await signOut.trigger()
        },
        [close, signOut],
    )

    return (
        <Dropdown.Menu>
            <Dropdown.Section>
                <Dropdown.Item
                    id="dashboard"
                    textValue={t("nav.dashboard")}
                    onPress={() => go(pathConfig().locale().dashboard().build())}
                >
                    <SquaresFourIcon className="size-5" />
                    <Label>{t("nav.dashboard")}</Label>
                </Dropdown.Item>
                <Dropdown.Item
                    id="profile"
                    textValue={t("nav.profile")}
                    onPress={() => go(pathConfig().locale().profile().build())}
                >
                    <UserIcon className="size-5" />
                    <Label>{t("nav.profile")}</Label>
                </Dropdown.Item>
                <Dropdown.Item
                    id="cv"
                    textValue={t("cv.title")}
                    onPress={() => go(pathConfig().locale().profile().cv().build())}
                >
                    <FileTextIcon className="size-5" />
                    <Label>{t("cv.title")}</Label>
                </Dropdown.Item>
                <Dropdown.Item
                    id="settings"
                    textValue={t("profileSettings.title")}
                    onPress={() => go(pathConfig().locale().profile().settings().build())}
                >
                    <GearIcon className="size-5" />
                    <Label>{t("profileSettings.title")}</Label>
                </Dropdown.Item>
            </Dropdown.Section>
            <Dropdown.Section>
                <Dropdown.Item
                    id="logout"
                    textValue={t("nav.logout")}
                    className="text-danger-soft-foreground"
                    onPress={onLogout}
                >
                    <SignOutIcon className="size-5" />
                    <Label className="text-danger-soft-foreground">{t("nav.logout")}</Label>
                </Dropdown.Item>
            </Dropdown.Section>
        </Dropdown.Menu>
    )
}

"use client"

import React, { useCallback } from "react"
import {
    Dropdown,
    Label,
} from "@heroui/react"
import {
    SignInIcon,
    UserPlusIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { AuthenticationModalTab } from "@/redux/slices/tabs"
import { useAppDispatch } from "@/redux/hooks"
import { setAuthenticationModalTab } from "@/redux/slices/tabs"
import { useAccountMenuOverlayState, useAuthenticationOverlayState } from "@/hooks/zustand/overlay/hooks"

/** Props for {@link AccountMenuGuest}. */
export type AccountMenuGuestProps = Record<string, never>
/**
 * Account dropdown menu for SIGNED-OUT viewers: sign in + sign up, each opening
 * the authentication modal on its tab. Self-contained ΓÇö dispatches the auth tab,
 * closes the menu, and opens the overlay; takes no data props.
 *
 * @param props - optional className (placement only).
 */
export const AccountMenuGuest = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const { close } = useAccountMenuOverlayState()
    const { open: openAuthentication } = useAuthenticationOverlayState()

    /** Open the auth modal on the chosen tab, then close this dropdown. */
    const onAuth = useCallback(
        (tab: AuthenticationModalTab) => {
            dispatch(setAuthenticationModalTab(tab))
            close()
            openAuthentication()
        },
        [dispatch, close, openAuthentication],
    )

    return (
        <Dropdown.Menu>
            <Dropdown.Section>
                <Dropdown.Item
                    id="sign-in"
                    textValue={t("auth.signIn.submit")}
                    onPress={() => onAuth(AuthenticationModalTab.SignIn)}
                >
                    <SignInIcon className="size-5" />
                    <Label>{t("auth.signIn.submit")}</Label>
                </Dropdown.Item>
                <Dropdown.Item
                    id="sign-up"
                    textValue={t("auth.signUp.submit")}
                    onPress={() => onAuth(AuthenticationModalTab.SignUp)}
                >
                    <UserPlusIcon className="size-5" />
                    <Label>{t("auth.signUp.submit")}</Label>
                </Dropdown.Item>
            </Dropdown.Section>
        </Dropdown.Menu>
    )
}

"use client"
import { MoonIcon, SunIcon } from "@phosphor-icons/react"
import { Switch } from "@heroui/react"
import { useTheme } from "next-themes"
import React from "react"

/**
 * Props for {@link DarkLightModeSwitch}.
 */
export type DarkLightModeSwitchProps = Record<string, never>
/**
 * DarkLightModeSwitch ΓÇö round HeroUI toggle for dark/light mode, with a sun/moon
 * icon riding inside the thumb. Uses the native Switch sizing (no custom pixel
 * dimensions) so the track + thumb stay perfectly round.
 * @param props - optional root class name (placement only)
 */
export const DarkLightModeSwitch = () => {
    const { theme, setTheme } = useTheme()
    const isDarkMode = theme === "dark"
    return (
        <Switch
            isSelected={isDarkMode}
            onChange={(value) => setTheme(value ? "dark" : "light")}
            aria-label="Toggle dark mode"
            className={""}
        >
            {({ isSelected }) => (
                <Switch.Content>
                    <Switch.Control>
                        <Switch.Thumb>
                            <Switch.Icon>
                                {isSelected ? (
                                    <MoonIcon className="size-5 text-inherit" />
                                ) : (
                                    <SunIcon className="size-5 text-inherit" />
                                )}
                            </Switch.Icon>
                        </Switch.Thumb>
                    </Switch.Control>
                </Switch.Content>
            )}
        </Switch>
    )
}

"use client"

import React from "react"
import { UserCell } from "@/components/composites/lists/UserCell"
import { useAppSelector } from "@/redux/hooks"

/**
 * Props for {@link UserSummary}.
 */

/**
 * Header row for the account menu: the signed-in user's avatar + username +
 * email, rendered via the {@link UserCell} block (so it stays compact and matches
 * `Skeleton.UserCell`). Container: reads the user from redux.
 */
export const UserSummary = () => {
    const user = useAppSelector((state) => state.user.user)
    return (
        <UserCell
            username={user?.username ?? ""}
            avatar={user?.avatar}
            handle={user?.email ?? undefined}
        />
    )
}

import {
    useMemo,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    usePathname,
} from "@/i18n/navigation"
import {
    pathConfig,
} from "@/resources/path"
import type {
    NavbarItem,
} from "./types/navbar"

/**
 * Shared source of truth for the navbar's top-level nav entries.
 *
 * Desktop `NavLinks` and the mobile drawer both render off this same list so
 * adding/renaming a route only has one place to update. Pass
 * `includeCart: true` for the mobile drawer, which also surfaces the cart
 * entry that the desktop bar renders separately via `CartButton`.
 * @param options.includeCart - append a "cart" entry (mobile drawer only)
 */
export const useNavbarItems = ({ includeCart = false }: { includeCart?: boolean } = {}) => {
    const t = useTranslations()
    const locale = useLocale()
    const pathname = usePathname()

    return useMemo<Array<NavbarItem>>(() => {
        const items: Array<NavbarItem> = [
            {
                label: t("nav.home"),
                path: pathConfig().locale().home().build(),
                isActive: pathname === "/" || pathname === pathConfig().locale().home().build(),
            },
            {
                label: t("nav.courses"),
                path: pathConfig().locale().course().build(),
                isActive: pathname.startsWith(pathConfig().locale(locale).course().build()),
            },
            {
                label: t("nav.contact"),
                path: pathConfig().locale().contact().build(),
                isActive: pathname.startsWith(pathConfig().locale(locale).contact().build()),
            },
        ]
        if (includeCart) {
            items.push({
                label: t("cart.title"),
                path: pathConfig().locale().cart().build(),
                isActive: pathname.startsWith(pathConfig().locale(locale).cart().build()),
            })
        }
        return items
    }, [includeCart, locale, pathname, t])
}

import React from "react"
import {
    PersonalProjectDashboard,
    type PersonalProjectDashboardProps,
} from "@/components/blocks/learn/PersonalProjectDashboard"
import {
    PersonalProjectTaskPage,
    type PersonalProjectTaskPageProps,
} from "@/components/pages/PersonalProjectTaskPage"
import {
    PersonalProjectResultScreen,
    type PersonalProjectResultScreenProps,
} from "@/components/blocks/learn/PersonalProjectResultScreen"

/**
 * `_PersonalProjectWorkspaceLayout` ΓÇö the SRC TWIN of `.storybook/components/starci/
 * pages/PersonalProjectWorkspace/PersonalProjectWorkspace.tsx`. Presentational:
 * typed props, already resolved; no fetch/store/i18n (that's the connected half,
 * `./index.tsx`).
 *
 * SCREEN ΓÇö the personal-project route group's own content switch. See the
 * blueprint's file header for the full RULE 12 investigation (why this is a
 * `pages/` screen, not a `layouts/` wrapper) and for why this file is a thin
 * dispatch rather than a rebuild of any content.
 *
 * THREE LEAVES, one per `view` ΓÇö a STRUCTURAL fork (which of three disjoint
 * screens mounts), not a data state of one shape: `Dashboard` (`/personal-
 * project`), `Task` (`/personal-project/tasks/[taskId]`), `Result`
 * (`ΓÇª/result`). Each leaf hands the real, untouched prop surface of the screen
 * it dispatches to straight through ΓÇö this file invents no data shape of its
 * own. Each leaf renders the CONNECTED child export (`PersonalProjectDashboard`,
 * `PersonalProjectTaskPage`, `PersonalProjectResultScreen`), which in these twins
 * happen to be presentational (the children own no data of their own).
 */

/** Props for {@link _PersonalProjectWorkspaceLayout} ΓÇö see the file header for the `view` split. */
export type PersonalProjectWorkspaceLayoutProps =
    | ({ view: "dashboard" } & PersonalProjectDashboardProps)
    | ({ view: "task" } & PersonalProjectTaskPageProps)
    | ({ view: "result" } & PersonalProjectResultScreenProps)

/**
 * The personal-project route group's content switch. See the file header for
 * why this screen exists and why it owns none of its own DOM.
 *
 * @param props - {@link PersonalProjectWorkspaceLayoutProps}
 */
const _PersonalProjectWorkspaceLayout = (props: PersonalProjectWorkspaceLayoutProps) => {
    // No wrapper div (BLOCK-2): each of the three leaves below is this
    // screen's own root for the branch it renders. None of the three yet
    // accepts the `identity` prop from `_identity.ts` (`PersonalProjectDashboard`,
    // `PersonalProjectTaskPage`, `PersonalProjectResultScreen` all still draw
    // their OWN `data-tier="block"`/`"page"` on their own root) and none is
    // wrapped in a sibling frame here to carry this screen's identity instead
    // ΓÇö so this screen currently renders with no `data-tier="page"
    // data-component="PersonalProjectWorkspace"` node of its own anywhere in
    // the tree, rather than re-adding the raw div BLOCK-2 forbids.
    if (props.view === "dashboard") return <PersonalProjectDashboard {...props} />
    if (props.view === "task") return <PersonalProjectTaskPage {...props} />
    return <PersonalProjectResultScreen {...props} />
}

export { _PersonalProjectWorkspaceLayout }

import React from "react"
import { SettingsSidebarNav, type SettingsNavGroup } from "@/components/blocks/navigation/SettingsSidebarNav"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Container } from "@/components/frames/Container"
import { RailShell } from "@/components/frames/RailShell"

/**
 * `_SettingsLayout` ΓÇö the chrome wrapping every route under `/profile/(settings)`
 * (edit profile, appearance, security, sessions, course history, AI settings,
 * bookmarks, membership, installments). Ported 1:1 from the storybook blueprint
 * `starci/layouts/SettingsLayout`. The nav is the block's own two-leaf
 * `SettingsSidebarNav` (desktop rail + mobile pill strip, both always in the DOM)
 * beside a centered content measure, composed through `RailShell` ΓÇö the exact
 * leading-rail-beside-a-growing-body shape that frame's own header names this
 * file's legacy source as one of the two real call sites that motivated it.
 * Column-first on narrow screens, a row from `@app-md`.
 *
 * `body` is a BUILDABLE slot (`ComponentTypeWithSkeleton`, uncalled) handed
 * straight to `Container`'s own `body` slot ΓÇö never a bare `ReactNode` ΓÇö so the
 * connected {@link SettingsLayout} wraps whatever the Next.js route-group layout
 * hands it once, at the call site. It is deliberately NOT named `children`: React
 * reserves that name for nested elements, and a ComponentType handed in under it
 * reads as an element to every linter and every reader.
 */

/** Props for {@link _SettingsLayout}. */
export interface SettingsLayoutProps {
    /** The active settings page for the current route ΓÇö a buildable slot, mandatory. */
    body: ComponentTypeWithSkeleton
    /** Grouped settings destinations, forwarded to {@link SettingsSidebarNav} untouched. */
    groups: Array<SettingsNavGroup>
    /** Which destination's route is active right now. */
    activeHref: string
    /** Fired with the href the reader picked in the nav. */
    onNavigate: (href: string) => void
    /** Sidebar heading, e.g. "Settings". */
    title: string
    /** Localized label for the collapse control. */
    collapseLabel: string
    /** Localized label for the expand control. */
    expandLabel: string
    /** `localStorage` key persisting the collapsed flag. */
    storageKey: string
}

/**
 * The settings shell: nav rail beside a content measure, column-first, row from
 * `@app-md` ΓÇö `RailShell`'s own contract. See that frame's header for why this is
 * its own khung and why the rail never shrinks while the body absorbs the rest.
 *
 * @param props - {@link SettingsLayoutProps}
 */
const _SettingsLayout = ({
    body: Body,
    groups,
    activeHref,
    onNavigate,
    title,
    collapseLabel,
    expandLabel,
    storageKey,
}: SettingsLayoutProps) => {
    const navSlot: ComponentTypeWithSkeleton = () => (
        <SettingsSidebarNav
            groups={groups}
            activeHref={activeHref}
            onNavigate={onNavigate}
            title={title}
            collapseLabel={collapseLabel}
            expandLabel={expandLabel}
            storageKey={storageKey}
        />
    )

    const contentSlot: ComponentTypeWithSkeleton = () => (
        <Container size="md" padding={6} body={Body} />
    )

    return (
        <RailShell
            rail={navSlot}
            body={contentSlot}
            at="md"
            principle="layout-split"
            explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
            identity={{ tier: "layout", component: "SettingsLayout" }}
        />
    )
}

export { _SettingsLayout }

import { ChatsCircleIcon, SidebarSimpleIcon, SquareHalfIcon } from "@phosphor-icons/react"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import { ButtonRadioGroup, type ButtonRadioGroupItem } from "@/components/composites/buttons/ButtonRadioGroup"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { StackH } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/**
 * `ContentAiChatDrawer` ΓÇö the global "ask StarCi AI" chat panel in drawer
 * presentation. Presentational overlay only: `isOpen`/`onOpenChange` are plain
 * props, the overlay-store wiring lives in the mounting layout. Two structural
 * leaves by header shape: the mode switch present (desktop, where railΓçädrawer
 * is a real choice) versus absent (forced mobile). Which title text shows
 * (caller-supplied vs the block's fallback) is a data state. The chat body is a
 * placeholder (`SurfaceCard` + `EmptyState`) standing in for the real
 * `ChatThread`/`ChatComposer` blocks.
 */

/** Fixed accessible name for the mode switch ΓÇö see the file header on why this is not a prop. */
const MODE_SWITCH_ARIA_LABEL = "Switch AI chat display mode"

/** Fixed fallback drawer title ΓÇö see the file header on why this is not a caller prop. */
const FALLBACK_TITLE = "Ask StarCi AI"

/** Scope-cut gap copy ΓÇö see the file header's "SCOPE-CUT GAP" note. */
const BODY_GAP_TITLE = "AI conversation frame"
const BODY_GAP_DESCRIPTION =
    "This frame hasn't wired up a real ChatThread/ChatComposer yet ΓÇö the conversation will slot in here on a later build pass."

/** Which way the AI chat panel is presented right now. */
export type ContentAiChatDrawerMode = "rail" | "drawer"

/** The mode switch's two options ΓÇö icon-only, accessible name riding along as `sr-only` text. */
const MODE_ITEMS: Array<ButtonRadioGroupItem<ContentAiChatDrawerMode>> = [
    {
        value: "rail",
        content: (
            <>
                <SidebarSimpleIcon aria-hidden focusable="false" className="size-4" />
                <span className="sr-only">Rail mode</span>
            </>
        ),
    },
    {
        value: "drawer",
        content: (
            <>
                <SquareHalfIcon aria-hidden focusable="false" className="size-4" />
                <span className="sr-only">Drawer mode</span>
            </>
        ),
    },
]

/** Props for {@link _ContentAiChatDrawer}. */
export interface ContentAiChatDrawerProps {
    /** Whether the drawer is currently open. Forwarded to `DrawerShell`. */
    isOpen: boolean
    /** Open-state change handler (backdrop click, Escape, close button). Forwarded to `DrawerShell`. */
    onOpenChange: (open: boolean) => void
    /**
     * Which edge the panel slides from. The caller passes `"bottom"` on
     * mobile ΓÇö this block does not compute `isMobile` itself (see the file
     * header). @default "right"
     */
    placement?: "right" | "bottom"
    /** Resolved lesson/course title. Omitted ΓåÆ the block's own fixed fallback wording. */
    title?: string
    /** Which presentation mode is active. Omit together with {@link onModeChange} to hide the switch entirely. */
    mode?: ContentAiChatDrawerMode
    /** Fired with the mode the reader picked. Omit together with {@link mode} to hide the switch entirely. */
    onModeChange?: (mode: ContentAiChatDrawerMode) => void
}

/**
 * The global "ask StarCi AI" chat drawer. See the file header for the
 * open-state/header contract and the chat-body scope cut.
 *
 * @param props - {@link ContentAiChatDrawerProps}
 */
const _ContentAiChatDrawer = ({
    isOpen,
    onOpenChange,
    placement = "right",
    title,
    mode,
    onModeChange,
}: ContentAiChatDrawerProps) => {
    // Both halves of the switch must be present together ΓÇö a mode with nothing to
    // change it, or a handler with no mode to reflect, are both dead controls, so
    // neither renders unless both do.
    const hasModeSwitch = mode != null && onModeChange != null

    const titleAndModeSwitch = [
        () => (
            <Typography
                text={title ?? FALLBACK_TITLE}
                weight="bold"
                truncate
                classNames={["min-w-0", "flex-1"]}
            />
        ),
        ...(hasModeSwitch ? [() => (
            <ButtonRadioGroup
                items={MODE_ITEMS}
                value={mode as ContentAiChatDrawerMode}
                onChange={(next) => onModeChange?.(next)}
                ariaLabel={MODE_SWITCH_ARIA_LABEL}
            />
        )] : []),
    ]

    // `DrawerShell.header` only carries ONE Typography node, so a second element
    // beside it (the mode switch) has to compose its own wrapper ΓÇö which then
    // owns its own `pr-8` for the close button, same contract `AiQuotaModal`'s
    // caller-built header uses. `Box` is the frame tier's own escape hatch for
    // exactly this: a single-side padding no `Stack`/`Flex` prop can express.
    const header = () => (
        <Box className="pr-8">
            <StackH
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                justify="between"
                items={titleAndModeSwitch}
            />
        </Box>
    )

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={placement}
            header={header}
            identity={{ tier: "overlay", component: "ContentAiChatDrawer" }}
            body={() => (
                <SurfaceCard
                    body={() => (
                        <EmptyState
                            icon={ChatsCircleIcon}
                            title={BODY_GAP_TITLE}
                            description={BODY_GAP_DESCRIPTION}
                        />
                    )}
                />
            )}
        />
    )
}

export { _ContentAiChatDrawer }

import React from "react"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { Tabs, type TabItem } from "@/components/atoms/navigation/Tabs"
import { Typography } from "@/components/atoms/text/Typography"
import { Chip } from "@/components/atoms/chips/Chip"
import { LinkSeeMore } from "@/components/atoms/navigation/Link"
import { StackH, StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"
import { AiQuotaLane, type AiQuotaLaneData } from "@/components/blocks/ai/AiQuotaLane"
import { AiQuotaSubscriptionPanel } from "@/components/blocks/ai/AiQuotaSubscriptionPanel"
import {
    AiQuotaHistoryPanel,
    type AiQuotaHistoryChartPoint,
    type AiQuotaHistoryChargeItem,
} from "@/components/blocks/ai/AiQuotaHistoryPanel"

/**
 * `AiQuotaModal` ΓÇö the root overlay for "how much AI have I used": a dialog with the
 * current tier beside its title, a 3-way tab strip (Auto / Subscription / History),
 * and one link out to the full-usage page. Composes `ModalShell` + `Tabs` + the three
 * sibling `ai` blocks it switches between (`AiQuotaLane`, `AiQuotaSubscriptionPanel`,
 * `AiQuotaHistoryPanel`).
 *
 * Presentational: `isOpen`/`onOpenChange`/`activeTab`/`onTabChange`, plus each tab's
 * `isLoading`. `tier: null` reads as the free plan and shows no badge.
 */

/** Which paid AI plan the viewer is on. `null` = free plan, no badge shown. */
export type AiQuotaTier = "plus" | "pro" | "max" | null

/** The three tabs this modal switches between. */
export type AiQuotaModalTab = "auto" | "subscription" | "history"

/** Auto tab's data ΓÇö the lane the free/auto model draws against. */
export interface AiQuotaModalAutoState {
    /** The lane's two rolling windows. Unset while `isLoading` (or before the first fetch lands). */
    data?: AiQuotaLaneData
    /** `true` ΓåÆ this tab's own fetch is in flight. */
    isLoading: boolean
}

/** Subscription tab's data ΓÇö the same lane shape, read against the paid plan's own cap. */
export interface AiQuotaModalSubscriptionState {
    /** The lane's two rolling windows, once subscribed. Unset on the free plan or before load. */
    data?: AiQuotaLaneData
    /** `true` ΓåÆ this tab's own fetch is in flight. */
    isLoading: boolean
}

/** History tab's data ΓÇö the usage chart plus the recent-charges list. */
export interface AiQuotaModalHistoryState {
    /** Day-buckets for the usage chart. */
    chartPoints?: Array<AiQuotaHistoryChartPoint>
    /** Recent charges, most recent first. `undefined` while the first load is still running. */
    items?: Array<AiQuotaHistoryChargeItem>
    /** `true` while the charges list's first load is running. */
    isLoading: boolean
}

/** Props for {@link _AiQuotaModal}. */
export interface AiQuotaModalProps {
    /** Whether the modal is currently open. Forwarded to {@link ModalShell}. */
    isOpen: boolean
    /** Open-state change handler ΓÇö backdrop click, Escape, close button. Forwarded to {@link ModalShell}. */
    onOpenChange: (open: boolean) => void
    /** The viewer's current plan. Drives the header's tier chip (hidden when `null`). */
    tier: AiQuotaTier
    /** Which tab is showing. The CALLER owns this ΓÇö the block never picks its own tab (Rule 7). */
    activeTab: AiQuotaModalTab
    /** Fired with the tab the viewer picked. */
    onTabChange: (tab: AiQuotaModalTab) => void
    /** Auto tab's lane data. */
    auto: AiQuotaModalAutoState
    /**
     * Subscription tab's Premium lane data ΓÇö shape matches
     * `AiQuotaSubscriptionPanel`'s own `premiumLane` prop 1:1 (forwarded
     * straight through, unreshaped); `tier` above decides whether that panel
     * even reaches its lane leaf or shows the no-tier CTA instead.
     */
    subscription: AiQuotaModalSubscriptionState
    /** History tab's chart + charges data. */
    history: AiQuotaModalHistoryState
    /** Fired when the subscription tab's upgrade CTA is pressed. The caller owns what happens next (Rule 7). */
    onSubscribe: () => void
    /** Fired when the "view full usage" link is pressed. */
    onViewDetails: () => void
}

/** Tab ΓåÆ label. The block's own vocabulary (┬º14d.1), same pattern as `ContentModeNav`'s `MODE_LABEL`. */
const TAB_LABEL: Record<AiQuotaModalTab, string> = {
    auto: "Auto",
    subscription: "Subscription",
    history: "History",
}

/** Fixed tab order ΓÇö a 3-way switch, not caller-supplied labels (┬º14d.1). */
const TAB_ITEMS: Array<TabItem> = [
    { key: "auto", label: TAB_LABEL.auto },
    { key: "subscription", label: TAB_LABEL.subscription },
    { key: "history", label: TAB_LABEL.history },
]

/** Paid tier ΓåÆ its badge label. */
const TIER_LABEL: Record<Exclude<AiQuotaTier, null>, string> = {
    plus: "Plus",
    pro: "Pro",
    max: "Max",
}

/**
 * The quota-modal scaffold. See the file header for the full contract and the
 * judgement calls made composing it out of the `ai`-group sibling blocks.
 *
 * @param props - {@link AiQuotaModalProps}
 */
const _AiQuotaModal = ({
    isOpen,
    onOpenChange,
    tier,
    activeTab,
    onTabChange,
    auto,
    subscription,
    history,
    onSubscribe,
    onViewDetails,
}: AiQuotaModalProps) => {
    // Caller-built header (title + optional tier chip): `ModalShell.header` only carries ONE
    // component reference, so a second element beside it (the chip) has to compose its own
    // wrapper ΓÇö which then owns its own `pr-8` for the close button, the same contract
    // `ContentAiChatDrawer`'s caller-built header uses. `Box` is the frame tier's own escape
    // hatch for exactly this: single-side padding no `Stack`/`Flex` prop can express.
    const titleAndTierChip = [
        () => (
            <Typography
                size="base"
                weight="bold"
                text="AI usage"

            />
        ),
        ...(tier != null ? [() => (
            <Chip tone="accent" text={TIER_LABEL[tier]} />
        )] : []),
    ]

    const header = () => (
        <Box className="pr-8">
            <StackH
                gap={3}
                principle="identity"
                explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                align="center"
                items={titleAndTierChip}
            />
        </Box>
    )

    // The one panel slot, filled by whichever sibling block the active tab names. The wrapper
    // shape around it never changes (┬º11f) ΓÇö see file header.
    const panel =
        activeTab === "auto" ? (
            <AiQuotaLane
                data={auto.data}
                isLoading={auto.isLoading}


            />
        ) : activeTab === "subscription" ? (
            <AiQuotaSubscriptionPanel
                tier={tier}
                premiumLane={subscription}
                onSubscribe={onSubscribe}


            />
        ) : (
            <AiQuotaHistoryPanel
                chartPoints={history.chartPoints}
                items={history.items}
                isLoading={history.isLoading}


            />
        )

    const tabsAndPanel = [
        () => (
            <Tabs
                items={TAB_ITEMS}
                selectedKey={activeTab}
                onSelectionChange={(key) => onTabChange(key as AiQuotaModalTab)}
                ariaLabel="AI usage"
            />
        ),
        () => panel,
    ]

    return (
        <ModalShell
            identity={{ tier: "overlay", component: "AiQuotaModal" }}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            header={header}
            size="lg"
            scroll="inside"
            footer={() => (
                <LinkSeeMore
                    label="View full usage"
                    onPress={onViewDetails}
                    size="sm"

                />
            )}
            body={() => <StackV gap={6} items={tabsAndPanel} />}
        />
    )
}

