"use client"

/**
 * Sign-up step: registration form (email, passwords, terms).
 *
 * Container: owns the sign-up formik (singleton `useSignUpForm()`) and the
 * switch-to-sign-in action; resolves i18n; hands resolved props to the
 * presentational {@link _RegistrationState}. See `tiers/split.md`.
 */
import React, {
    useCallback,
} from "react"
import { useTranslations } from "next-intl"
import { _RegistrationState } from "./component"
import { useAppDispatch } from "@/redux/hooks"
import { AuthenticationModalTab, setAuthenticationModalTab } from "@/redux/slices/tabs"
import { resetSignUpState } from "@/redux/slices/state"
import { useSignUpForm } from "@/hooks/zustand/signUp/useSignUpForm"
import { publicEnv } from "@/resources/env/public"

/** Props for {@link RegistrationState}. */
export interface RegistrationStateProps {
    /** Hides `Modal.CloseTrigger` when hosted outside a dismissible modal (the `/login` page). */
    hideCloseButton?: boolean
}

/**
 * Registration form container for the sign-up tab.
 */
export const RegistrationState = ({ hideCloseButton }: RegistrationStateProps = {}) => {
    const dispatch = useAppDispatch()
    const t = useTranslations()
    const {
        values,
        errors,
        touched,
        submitForm,
        setFieldValue,
        setFieldTouched,
        isSubmitting,
        resetForm,
        isValid,
    } = useSignUpForm()

    // `Input.*` atoms carry no `onBlur` ΓÇö the field is marked touched on its
    // first edit instead (same combined value+touch shape already used for
    // `agreeToTerms` below), so the inline error still gates on interaction.
    const onChangeEmail = useCallback(
        (value: string) => {
            setFieldValue("email", value)
            setFieldTouched("email", true)
        },
        [
            setFieldValue,
            setFieldTouched,
        ],
    )

    const onChangePassword = useCallback(
        (value: string) => {
            setFieldValue("password", value)
            setFieldTouched("password", true)
        },
        [
            setFieldValue,
            setFieldTouched,
        ],
    )

    const onChangeConfirmPassword = useCallback(
        (value: string) => {
            setFieldValue("confirmPassword", value)
            setFieldTouched("confirmPassword", true)
        },
        [
            setFieldValue,
            setFieldTouched,
        ],
    )

    const onChangeAgreeToTerms = useCallback(
        (selected: boolean) => {
            // third arg true: run validation so `errors.agreeToTerms` clears when checked
            setFieldValue("agreeToTerms", selected, true)
            setFieldTouched("agreeToTerms", true, false)
        },
        [
            setFieldValue,
            setFieldTouched,
        ],
    )

    const onSubmit = useCallback(
        () => {
            submitForm()
        },
        [
            submitForm,
        ],
    )

    /** Reset the form + sign-up state, then switch to the sign-in tab. */
    const onSwitchToSignIn = useCallback(
        () => {
            resetForm()
            dispatch(resetSignUpState())
            dispatch(setAuthenticationModalTab(AuthenticationModalTab.SignIn))
        },
        [
            resetForm,
            dispatch,
        ],
    )

    const onCaptchaVerify = useCallback(
        (token: string) => {
            setFieldValue("captchaToken", token)
        },
        [
            setFieldValue,
        ],
    )
    const onCaptchaExpire = useCallback(
        () => {
            setFieldValue("captchaToken", undefined)
        },
        [
            setFieldValue,
        ],
    )
    const onCaptchaError = useCallback(
        () => {
            setFieldValue("captchaToken", undefined)
        },
        [
            setFieldValue,
        ],
    )

    const captchaEnabled = publicEnv().captcha.enabled
    const isSubmitDisabled = !isValid || (captchaEnabled && !values.captchaToken)

    return (
        <_RegistrationState
            hideCloseButton={hideCloseButton}
            values={values}
            errors={errors}
            touched={touched}
            isSubmitting={isSubmitting}
            isSubmitDisabled={isSubmitDisabled}
            captchaEnabled={captchaEnabled}
            labels={{
                title: t("auth.signUp.title"),
                desc: t("auth.signUp.desc"),
                submit: t("auth.signUp.submit"),
            }}
            onChangeEmail={onChangeEmail}
            onChangePassword={onChangePassword}
            onChangeConfirmPassword={onChangeConfirmPassword}
            onChangeAgreeToTerms={onChangeAgreeToTerms}
            onSubmit={onSubmit}
            onSwitchToSignIn={onSwitchToSignIn}
            onCaptchaVerify={onCaptchaVerify}
            onCaptchaExpire={onCaptchaExpire}
            onCaptchaError={onCaptchaError}
        />
    )
}

"use client"

/**
 * Sign-up section inside {@link AuthenticationModal}.
 *
 * Mirrors {@link SignInSection}: router on Redux `state.signUpState`.
 * Flow: **Registration** (`signUpInit`) ΓåÆ **Otp** (`signUpVerifyOtp`).
 *
 * ### Data layer
 * - {@link useMutateSignUpSwr} ΓÇö GraphQL `signUpInit` (SWR singleton).
 * - {@link useMutateSignUpVerifyOtpSwr} ΓÇö GraphQL `signUpVerifyOtp`.
 * - {@link useSignUpForm} ΓÇö submit branches + `challengeId` / `otp` values.
 */
import React from "react"
import { RegistrationState } from "./RegistrationState"
import { OtpState } from "./OtpState"
import { useAppSelector } from "@/redux/hooks"
import { SignUpState } from "@/redux/slices/state"

/** Props for {@link SignUpSection}. */
export interface SignUpSectionProps {
    /** Hides `Modal.CloseTrigger` on both steps when hosted outside a dismissible modal (the `/login` page). */
    hideCloseButton?: boolean
}

/**
 * Renders the active sign-up step from `signUpState`.
 */
export const SignUpSection = ({ hideCloseButton }: SignUpSectionProps = {}) => {
    const signUpState = useAppSelector((state) => state.state.signUpState)
    switch (signUpState) {
    case SignUpState.Registration:
        return <RegistrationState hideCloseButton={hideCloseButton} />
    case SignUpState.Otp:
        return <OtpState hideCloseButton={hideCloseButton} />
    default:
        return null
    }
}

import React, { useEffect, useState } from "react"
import { Button } from "@/components/atoms/buttons/Button"
import { ChoiceSwitch } from "@/components/atoms/forms"
import { StackV } from "@/components/frames/Stack"
import { ModalShell } from "@/components/composites/layout/ModalShell"

/**
 * All display text for {@link _CookieConsentModal}, already localized by the connected
 * `CookieConsentModal` ΓÇö a story passes the bare i18n keys.
 */
export interface CookieConsentModalLabels {
    /** Dialog title. */
    modalTitle: string
    /** Explanatory copy under the title. */
    modalBody: string
    /** Necessary-cookies row label (always-on category). */
    necessaryLabel: string
    /** Necessary-cookies row hint. */
    necessaryHint: string
    /** Analytics-cookies row label (toggleable category). */
    analyticsLabel: string
    /** Analytics-cookies row hint. */
    analyticsHint: string
    /** Save (commit the draft toggle) button label. */
    save: string
    /** Reject-all button label. */
    reject: string
    /** Accept-all button label. */
    acceptAll: string
}

/** Props for {@link _CookieConsentModal} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface CookieConsentModalProps {
    /** Whether the modal is currently open. Forwarded to {@link ModalShell}. */
    isOpen: boolean
    /** Open-state change handler ΓÇö backdrop click, Escape, close button. Forwarded to {@link ModalShell}. */
    onOpenChange: (open: boolean) => void
    /** The visitor's currently COMMITTED analytics choice ΓÇö seeds the draft toggle each time the modal opens. */
    analyticsAllowed: boolean
    /** Commits the draft analytics choice (Save was pressed). The caller also closes the modal. */
    onSave: (analyticsAllowed: boolean) => void
    /** Rejects every optional category (Reject was pressed). The caller also closes the modal. */
    onReject: () => void
    /** Accepts every category (Accept-all was pressed). The caller also closes the modal. */
    onAcceptAll: () => void
    /** All display text ΓÇö see {@link CookieConsentModalLabels}. */
    labels: CookieConsentModalLabels
}

/**
 * Cookie preferences modal ΓÇö the presentational half of `CookieConsentModal`: the granular
 * "Customize" panel ΓÇö Necessary (locked on) + Analytics (toggle), via {@link ChoiceSwitch}'s
 * own label+hint composition ΓÇö with Save / Reject / Accept-all in the dialog footer (a real
 * `ModalShell` footer slot, not a hand-rolled row inside the body). Composes `ModalShell` +
 * `ChoiceSwitch` + `Button`. Holds its OWN draft toggle, re-seeded from
 * {@link CookieConsentModalProps.analyticsAllowed} each time the modal opens ΓÇö same shape
 * `SubmissionResultHistoryDrawer` uses to reset its own page on open. See `tiers/split.md`.
 *
 * @param props - {@link CookieConsentModalProps}
 */
export const _CookieConsentModal = ({
    isOpen,
    onOpenChange,
    analyticsAllowed,
    onSave,
    onReject,
    onAcceptAll,
    labels,
}: CookieConsentModalProps) => {
    // draft toggle ΓÇö re-seed from the committed value whenever the modal opens
    const [analyticsDraft, setAnalyticsDraft] = useState(analyticsAllowed)
    useEffect(() => {
        if (isOpen) {
            setAnalyticsDraft(analyticsAllowed)
        }
    }, [isOpen, analyticsAllowed])

    const switchRows = [
        () => (
            <ChoiceSwitch
                isSelected
                isDisabled
                onValueChange={() => { /* locked on ΓÇö always granted */ }}
                label={labels.necessaryLabel}
                hint={labels.necessaryHint}
            />
        ),
        () => (
            <ChoiceSwitch
                isSelected={analyticsDraft}
                onValueChange={setAnalyticsDraft}
                label={labels.analyticsLabel}
                hint={labels.analyticsHint}
            />
        ),
    ]

    return (
        <ModalShell
            identity={{ tier: "overlay", component: "CookieConsentModal" }}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            title={labels.modalTitle}
            description={labels.modalBody}
            body={() => <StackV gap={6} items={switchRows} />}
            footer={() => (
                <>
                    <Button
                        variant="primary"
                        size="sm"
                        label={labels.save}
                        onPress={() => onSave(analyticsDraft)}
                    />
                    <Button
                        variant="secondary"
                        size="sm"
                        label={labels.reject}
                        onPress={onReject}
                    />
                    <Button
                        variant="tertiary"
                        size="sm"
                        label={labels.acceptAll}
                        onPress={onAcceptAll}
                    />
                </>
            )}
        />
    )
}

import { InputSearch } from "@/components/atoms/forms"
import React from "react"
import {
    CardsIcon,
    CheckSquareIcon,
    FileTextIcon,
    FlagIcon,
    GraduationCapIcon,
    LightbulbIcon,
    PuzzlePieceIcon,
    StackIcon,
} from "@phosphor-icons/react"
import type { Icon as PhosphorIcon } from "@phosphor-icons/react"
import { ModalShell } from "@/components/composites/layout/ModalShell"

import { Typography } from "@/components/atoms/text/Typography"
import { Cluster } from "@/components/frames/Cluster"
import { StackV } from "@/components/frames/Stack"
import { GlobalSearchContent } from "./Content"

/**
 * `_GlobalSearchModal` ΓÇö the presentational half of `GlobalSearchModal`, the
 * keyboard-first command palette opened by the Navbar (Ctrl/Cmd+K). Composes
 * `ModalShell`: a search field header, a grouped-results/popular-fallback
 * body (`GlobalSearchContent`), and a keyboard-hint footer row. Every field
 * arrives already resolved ΓÇö no store, no fetch, no `t()` (see `./index.tsx`).
 *
 * MISSING VOCABULARY (documented, not invented here ΓÇö see the task's
 * `missingVocabulary` report): the design system has no atom wrapping a
 * `Kbd`-style keycap chip, so the shortcut hints render as plain
 * `Typography` instead of key-cap glyphs; `InputSearch` exposes neither
 * `autoFocus` nor `onKeyDown`, so the palette no longer autofocuses on open
 * nor moves focus into the results on ArrowDown; and there is no
 * roving-tabindex "options list" composite (the old raw HeroUI `ListBox`
 * gave ΓåæΓåô arrow-key navigation between rows for free) ΓÇö results render
 * through `SurfaceCardList` instead, which is Tab-order only.
 */

/** Entity bucket a pressed search item belongs to ΓÇö drives its leading icon. */
export type GlobalSearchKind =
    | "course"
    | "module"
    | "content"
    | "challenge"
    | "flashcardDeck"
    | "milestone"
    | "milestoneTask"
    | "foundation"

/** Leading icon per result kind (phosphor) ΓÇö a required classifier in a mixed result list. */
export const GLOBAL_SEARCH_KIND_ICON: Record<GlobalSearchKind, PhosphorIcon> = {
    course: GraduationCapIcon,
    module: StackIcon,
    content: FileTextIcon,
    challenge: PuzzlePieceIcon,
    flashcardDeck: CardsIcon,
    milestone: FlagIcon,
    milestoneTask: CheckSquareIcon,
    foundation: LightbulbIcon,
}

/** One resolved search-result row ΓÇö already carries which badges to show; no raw `t()`/store left to read. */
export interface GlobalSearchResultRow {
    /** Stable row key. */
    id: string
    /** Kind of this row ΓÇö picks the leading icon. */
    kind: GlobalSearchKind
    /** Primary title line. */
    title: string
    /** Additional matched text snippets, may carry `<em>ΓÇª</em>` markup around the matched span. */
    textLines: Array<string>
    /** Server-built deep link; rows with no path are not actionable. */
    path?: string | null
    /** `true` ΓåÆ an "Enrolled" chip (course rows the viewer already owns). */
    showEnrolledChip: boolean
    /** `true` ΓåÆ a "Free" chip (a not-enrolled free course, or a non-premium lesson). */
    showFreeChip: boolean
    /** `true` ΓåÆ a muted lock glyph (a premium lesson the viewer hasn't unlocked). */
    showPremiumLock: boolean
    /** `true` ΓåÆ the trailing "View course ΓåÆ" hint (course rows only). */
    showViewCourseHint: boolean
}

/** One grouped section of results ΓÇö one non-empty bucket, header label already interpolated with its count. */
export interface GlobalSearchModalSection {
    /** Bucket kind ΓÇö also this section's stable key. */
    kind: GlobalSearchKind
    /** Already-translated `"Courses (3)"`-style heading. */
    label: string
    /** Rows in this bucket. */
    items: Array<GlobalSearchResultRow>
}

/** One popular-course fallback row shown while the palette is idle or has no matches. */
export interface GlobalSearchModalPopularCourse {
    /** Stable row key. */
    id: string
    /** Public slug ΓÇö the connected half routes on this when pressed. */
    displayId: string
    /** Course title. */
    title: string
    /** The viewer's loyalty-discounted price. */
    discountedPriceVnd: number
}

/** Every translated string this modal renders, resolved by the connected half. */
export interface GlobalSearchModalLabels {
    /** Search-field placeholder. */
    placeholder: string
    /** "ΓåæΓåô to navigate" hint. */
    hintMove: string
    /** "Γå╡ to open" hint. */
    hintOpen: string
    /** "Esc to close" hint. */
    hintClose: string
    /** Shown when a query was typed but matched nothing. */
    noResults: string
    /** Shown when the query is blank (idle palette). */
    idleHint: string
    /** "Popular" fallback-list heading. */
    popular: string
    /** "Enrolled" chip text. */
    enrolled: string
    /** "Free" chip text. */
    free: string
    /** "View course" trailing hint text. */
    viewCourse: string
    /** Accessible label for the premium-lock glyph. */
    premiumLock: string
}

/** Props for {@link _GlobalSearchModal}. */
export interface GlobalSearchModalProps {
    /** Whether the palette is open. */
    isOpen: boolean
    /** Open-state change handler (backdrop, Escape, close trigger). */
    onOpenChange: (open: boolean) => void
    /** Current (uncommitted) search-field text. */
    query: string
    /** Fires on every keystroke. */
    onQueryChange: (value: string) => void
    /** Non-empty result buckets, in display order. */
    sections: Array<GlobalSearchModalSection>
    /** `true` once a non-blank query has been committed ΓÇö switches the empty state's copy. */
    hasQuery: boolean
    /** Popular-course fallback rows (idle palette, or a query with no hits). */
    popularCourses: Array<GlobalSearchModalPopularCourse>
    /** Every translated string this modal renders. */
    labels: GlobalSearchModalLabels
    /** Fired when a result row is pressed. */
    onSelectResult: (row: GlobalSearchResultRow) => void
    /** Fired when a popular-course fallback row is pressed. */
    onSelectPopularCourse: (course: GlobalSearchModalPopularCourse) => void
}

/**
 * The keyboard-first search command palette. See the file header for the
 * full contract and the documented vocabulary gaps.
 *
 * @param props - {@link GlobalSearchModalProps}
 */
export const _GlobalSearchModal = ({
    isOpen,
    onOpenChange,
    query,
    onQueryChange,
    sections,
    hasQuery,
    popularCourses,
    labels,
    onSelectResult,
    onSelectPopularCourse,
}: GlobalSearchModalProps) => {
    const header = () => (
        <InputSearch
            ariaLabel={labels.placeholder}
            placeholder={labels.placeholder}
            value={query}
            onValueChange={onQueryChange}
        />
    )

    const body = () => (
        <StackV
            gap={5}
            items={[
                () => (
                    <GlobalSearchContent
                        sections={sections}
                        hasQuery={hasQuery}
                        popularCourses={popularCourses}
                        labels={labels}
                        onSelectResult={onSelectResult}
                        onSelectPopularCourse={onSelectPopularCourse}
                    />
                ),
                () => (
                    // The plain "ΓåæΓåô"/"Γå╡" glyphs are universal symbols, not translated
                    // copy ΓÇö composed here (not baked into the i18n string) exactly
                    // like `Content/index.tsx` composes a section's translated label
                    // with its own count. `hintClose` already spells out "esc" in
                    // every locale (`search.hint.close`), so it needs no glyph prefix.
                    <Cluster
                        gap={5}
                        items={[
                            () => <Typography size="xs" color="muted" text={`ΓåæΓåô ${labels.hintMove}`} />,
                            () => <Typography size="xs" color="muted" text={`Γå╡ ${labels.hintOpen}`} />,
                            () => <Typography size="xs" color="muted" text={labels.hintClose} />,
                        ]}
                    />
                ),
            ]}
        />
    )

    return (
        <ModalShell
            identity={{ tier: "overlay", component: "GlobalSearchModal" }}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            size="lg"
            scroll="inside"
            header={header}
            body={body}
        />
    )
}

"use client"

import React, { useState } from "react"
import { useTranslations } from "next-intl"
import { useSWRConfig } from "swr"
import { QUERY_USER_PINNED_PROJECTS_SWR } from "@/hooks/swr/api/graphql/queries/useQueryUserPinnedProjectsSwr"
import { useMutatePinCourseProjectSwr } from "@/hooks/swr/api/graphql/mutations/useMutatePinCourseProjectSwr"
import { useQueryMyPinnableCapstonesSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyPinnableCapstonesSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { useAppSelector } from "@/redux/hooks"
import { _CourseProjectForm, type CourseProjectFormOption } from "./component"

/** Props for {@link CourseProjectForm}. */
export interface CourseProjectFormProps {
    /** Called after a successful pin (close the modal / switch to the list). */
    onSuccess?: () => void
}

/**
 * Form for pinning one of the signed-in user's capstone projects ΓÇö the
 * CONNECTED half. Loads the pinnable capstones via
 * {@link useQueryMyPinnableCapstonesSwr}, owns the picker + description local
 * state, submits via {@link useMutatePinCourseProjectSwr} through
 * {@link useGraphQLWithToast}. On success: revalidates the viewer's
 * pinned-projects SWR key, resets state, and calls `onSuccess`. See
 * `tiers/split.md`.
 *
 * @param props - {@link CourseProjectFormProps}
 */
export const CourseProjectForm = ({
    onSuccess,
}: CourseProjectFormProps = {}) => {
    const t = useTranslations()
    const { mutate } = useSWRConfig()
    const runGraphQL = useGraphQLWithToast()

    // the signed-in viewer ΓÇö needed to revalidate the correct SWR cache key
    const viewerId = useAppSelector((state) => state.user.user?.id)

    // load the user's pinnable capstones (enrollment rows that have a project repo)
    const { data: capstones, isLoading, error: capstonesError, mutate: mutateCapstones } = useQueryMyPinnableCapstonesSwr()
    const options: Array<CourseProjectFormOption> = (capstones ?? []).map((item) => ({
        enrollmentId: item.enrollmentId,
        courseTitle: item.courseTitle,
        isVerified: item.isVerified,
    }))

    // controlled selection: the enrollmentId of the chosen capstone, or null
    const [selectedEnrollmentId, setSelectedEnrollmentId] = useState<string | null>(null)
    // optional description the user types in
    const [description, setDescription] = useState("")
    // in-flight submit guard
    const [isSubmitting, setIsSubmitting] = useState(false)

    // the SWR mutation that calls pinCourseProject on the backend
    const pinSwr = useMutatePinCourseProjectSwr()

    /** Submit the pin mutation and revalidate on success. */
    const onSubmit = async () => {
        // require a capstone to be selected before submitting
        if (!selectedEnrollmentId) return

        setIsSubmitting(true)
        await runGraphQL(
            async () => {
                // call the pinCourseProject GraphQL mutation
                const result = await pinSwr.trigger({
                    enrollmentId: selectedEnrollmentId,
                    description: description.trim() || undefined,
                })
                const env = result?.data?.pinCourseProject
                if (!env) {
                    throw new Error(t("toast.defaultError"))
                }
                // on success: revalidate the owner's pinned list, reset state, close
                if (env.success) {
                    if (viewerId) {
                        // bust the viewer's cached pinned-projects list
                        await mutate([QUERY_USER_PINNED_PROJECTS_SWR, viewerId])
                    }
                    // reset form state to blank
                    setSelectedEnrollmentId(null)
                    setDescription("")
                    onSuccess?.()
                }
                return env
            },
            {
                showErrorToast: true,
                showSuccessToast: true,
            },
        )
        setIsSubmitting(false)
    }

    return (
        <_CourseProjectForm
            options={options}
            selectedEnrollmentId={selectedEnrollmentId}
            onSelectedEnrollmentIdChange={setSelectedEnrollmentId}
            description={description}
            onDescriptionChange={setDescription}
            isLoading={isLoading}
            isSubmitting={isSubmitting}
            isError={Boolean(capstonesError)}
            onRetry={() => { void mutateCapstones() }}
            onSubmit={onSubmit}
            labels={{
                selectLabel: t("pinnedProjects.course.selectLabel"),
                loading: t("pinnedProjects.course.loading"),
                selectPlaceholder: t("pinnedProjects.course.selectPlaceholder"),
                verified: t("pinnedProjects.course.verified"),
                description: t("pinnedProjects.form.description"),
